      lbl(S, 'l1', 19.0, 3.35, ['6ms 안에 답이 없으면 같은 요청을 한 번 더 보냈어요 · N=10의 p99가 51.7에서 11.9ms로', 'resending after 6 ms without a reply cut the N=10 p99 from 51.7 to 11.9 ms'], 'g', 1, { w: 12.4 });
      lbl(S, 'l2', 19.0, 4.75, ['추가 요청은 2%뿐이었어요 · 느린 1%만 다시 보냈기 때문이에요', 'only 2% extra requests, since just the slow 1% were resent'], 'g', 2, { w: 12.4 });
      lbl(S, 'l3', 19.0, 6.15, ['N=100에서는 서버가 붐벼 6ms를 넘는 일이 잦아져 추가 요청이 24.6%로 불었어요', 'at N=100 the busy server often exceeded 6 ms, inflating extra requests to 24.6%'], 'w', 3, { w: 12.4 });
