      lbl(S, 'm1', 1, 7.0, ['빗나간 요청만 DB로 가요 · 58.6%면 DB 부하가 41.4%로 줄어요', 'only misses reach the DB: at 58.6%, DB load drops to 41.4%'], 'g', 4, { w: 16.0 });
