      lbl(S, 'l1', 19.0, 2.85, ['301은 브라우저가 기억해 두 번째부터는 서버에 묻지 않고 바로 이동했어요', 'browsers remembered the 301 and went straight there from the second visit'], 'a', 1, { w: 12.4 });
