      T(S, 't3', 19.0, 5.1, ['Redis INCR: 65,475/s · p50 0.34ms', 'Redis INCR: 65,475/s · p50 0.34 ms'], 'cz-mono sdx-tiny sdx-a', 3, { w: 12.4 });
      lbl(S, 'l3', 19.0, 5.7, ['메모리에서 한 스레드로 더하는 Redis는 잠금 없이 10배 빨랐어요', 'Redis, adding in memory on one thread, was 10× faster with no locks'], 'a', 3, { w: 12.4 });
