      lbl(S, 'l1', 19.0, 2.3, ['마지막 구독자가 받기까지의 중간값이에요 · 구독자 수에 비례해 늘었어요', 'median time until the last subscriber received it: grew with subscribers'], 'a', 1, { w: 12.4 });
      mono(S, 'm2', 19.0, 3.7, nbs([['끊긴 동안 PUBLISH → 받은 곳 0', 'offline PUBLISH → 0 receivers'], ['다시 접속: m2, m3 없음', 'reconnect: m2, m3 lost'], ['스트림: 마지막 id 뒤 → m2, m3', 'stream: after last id → m2, m3']]), 2, { w: 12.4, dy: .55, c: 'sdx-w' });
